{ \True Diện tích hình giới hạn bởi hai tiếp tuyến $MA, MB$ và cung nhỏ $AB$ bằng $36\left(\dfrac{\sqrt{3}}{3} - \dfrac{\pi}{6}\right)\text{ cm}^2$ }
}{
\begin{tikzpicture}[scale=0.68, font=\footnotesize, line cap=round, line join=round]
  \def\R{2.1}
  \coordinate (O) at (0,0);
  \coordinate (A) at (55:\R);
  \coordinate (B) at (-55:\R);
  \coordinate (C) at (155:\R);
  \pgfmathsetmacro{\xm}{\R/cos(55)}
  \coordinate (M) at (\xm,0);
  \draw[thick] (O) circle (\R);
  \draw (C)--(A) (C)--(B) (O)--(A) (O)--(B) (M)--(A) (M)--(B) (O)--(M);
  \foreach \p/\pos/\lb in {O/left/O, A/above/A, B/below/B, C/left/C, M/right/M}{
    \fill (\p) circle (1.5pt) node[\pos]{\lb};
  }
\end{tikzpicture}
}
\loigiai{
a) \textbf{Đúng}. Góc ở tâm $\widehat{AOB}$ chắn cung nhỏ $AB$ bằng hai lần góc nội tiếp cùng chắn cung $AB$: $\text{sđ}\wideparen{AB} = \widehat{AOB} = 2\widehat{ACB} = 2 \cdot 30^\circ = 60^\circ$.\\
b) \textbf{Đúng}. Theo tính chất hai tiếp tuyến cắt nhau, $OM$ là tia phân giác của $\widehat{AOB}$ nên $\widehat{AOM} = 30^\circ$. Trong $\triangle OAM$ vuông tại $A$: $AM = OA \cdot \tan 30^\circ = 6 \cdot \dfrac{\sqrt{3}}{3} = 2\sqrt{3}$ (cm).\\
c) \textbf{Đúng}. Ta có $\widehat{OAM} = \widehat{OBM} = 90^\circ$ nên hai đỉnh $A, B$ cùng nhìn đoạn $OM$ dưới một góc vuông; vậy $4$ điểm $A, O, B, M$ cùng thuộc đường tròn đường kính $OM$ (tâm là trung điểm $OM$).\\
d) \textbf{Đúng}. Diện tích hình cần tính bằng diện tích tứ giác $OAMB$ trừ diện tích hình quạt tròn $OAB$: $S = 2S_{\triangle OAM} - S_{\text{quạt}} = 6 \cdot 2\sqrt{3} - \dfrac{60\pi \cdot 6^2}{360} = 36\left(\dfrac{\sqrt{3}}{3} - \dfrac{\pi}{6}\right)$ ($\text{cm}^2$).
}\end{ex}
